import React, { useRef, useEffect } from 'react';

interface TimelineProps {
  buffer: { getChannelData: (ch: number) => Float32Array } | null;
  loopStart: number;
  loopEnd: number;
  progress: number;
  onLoopChange: (start: number, end: number) => void;
  onSeek?: (normPos: number) => void;
  onPan?: (deltaNorm: number) => void;
  onZoom?: (factor: number, centerNorm: number) => void;
}

const Timeline: React.FC<TimelineProps> = ({ buffer, loopStart, loopEnd, progress, onLoopChange, onSeek, onPan, onZoom }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // Drag state
  const dragMode = useRef<'start' | 'end' | 'pan' | null>(null);
  const dragStartX = useRef(0);
  const dragStartLoop = useRef({ start: loopStart, end: loopEnd });
  const HANDLE_PX = 16;

  // Draw Waveform — CRT green style
  useEffect(() => {
    if (!buffer || !canvasRef.current) return;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * window.devicePixelRatio;
    canvas.height = rect.height * window.devicePixelRatio;
    ctx.scale(window.devicePixelRatio, window.devicePixelRatio);
    const width = rect.width;
    const height = rect.height;
    ctx.clearRect(0, 0, width, height);
    const data = buffer.getChannelData(0);
    const step = Math.ceil(data.length / width);
    const amp = height / 2;
    // Green CRT waveform
    ctx.fillStyle = '#ff9900';
    ctx.shadowColor = 'rgba(255, 153, 0, 0.3)';
    ctx.shadowBlur = 2;
    for (let i = 0; i < width; i++) {
      let min = 1.0, max = -1.0;
      for (let j = 0; j < step; j++) {
        const val = data[(i * step) + j];
        if (val !== undefined) {
          if (val < min) min = val;
          if (val > max) max = val;
        }
      }
      ctx.fillRect(i, (1 + min) * amp, 1, Math.max(1, (max - min) * amp));
    }
    ctx.shadowBlur = 0;
  }, [buffer]);

  const getNormX = (clientX: number) => {
    if (!containerRef.current) return 0;
    const rect = containerRef.current.getBoundingClientRect();
    return Math.max(0, Math.min(1, (clientX - rect.left) / rect.width));
  };

  const handlePointerDown = (e: React.PointerEvent) => {
    if (!containerRef.current) return;
    e.currentTarget.setPointerCapture(e.pointerId);
    const rect = containerRef.current.getBoundingClientRect();
    const clickPx = e.clientX - rect.left;
    const startPx = loopStart * rect.width;
    const endPx   = loopEnd   * rect.width;

    if (Math.abs(clickPx - startPx) < HANDLE_PX) {
      dragMode.current = 'start';
    } else if (Math.abs(clickPx - endPx) < HANDLE_PX) {
      dragMode.current = 'end';
    } else {
      dragMode.current = 'pan';
      dragStartX.current = e.clientX;
      dragStartLoop.current = { start: loopStart, end: loopEnd };
    }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!dragMode.current || e.buttons === 0) return;
    const x = getNormX(e.clientX);
    if (dragMode.current === 'start') {
      if (x < loopEnd - 0.05) onLoopChange(x, loopEnd);
    } else if (dragMode.current === 'end') {
      if (x > loopStart + 0.05) onLoopChange(loopStart, x);
    } else if (dragMode.current === 'pan' && containerRef.current) {
      const rect = containerRef.current.getBoundingClientRect();
      const deltaNorm = (e.clientX - dragStartX.current) / rect.width;
      const newStart = dragStartLoop.current.start + deltaNorm;
      const newEnd   = dragStartLoop.current.end   + deltaNorm;
      if (newStart >= 0 && newEnd <= 1) onLoopChange(newStart, newEnd);
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (dragMode.current === 'pan') {
      if (Math.abs(e.clientX - dragStartX.current) < 5) {
        onSeek?.(getNormX(e.clientX));
      }
    }
    dragMode.current = null;
  };

  const handleWheel = (e: React.WheelEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();

    // Horizontal scroll (side-to-side) → pan loop region (Moves the "window")
    if (Math.abs(e.deltaX) > 1) {
      const deltaNorm = (e.deltaX / rect.width) * 0.8;
      onPan?.(deltaNorm);
    }

    // Vertical scroll (up and down) → scrub playhead (Reserved for playhead)
    // We treat deltaY exclusively as a scrub gesture, fulfilling the request
    // that the window should not be movable with up/down scroll.
    if (Math.abs(e.deltaY) > 1) {
      const scrubDelta = (e.deltaY / 100) * 0.02 * (e.shiftKey ? 4 : 1);
      // No clamp here; wrapping logic is handled in the parent onSeek.
      onSeek?.(progress + scrubDelta);
    }
  };

  if (!buffer) return (
    <div className="h-full w-full bg-[#0d0800] rounded flex items-center justify-center border border-[#1a2a1a] overflow-hidden relative">
      <span
        className="text-[#cc7a00] font-lcd text-xs uppercase tracking-widest opacity-50"
        style={{
          animation: 'signal-scan 2.5s ease-in-out infinite alternate',
        }}
      >Awaiting Buffer</span>
      <style>{`
        @keyframes signal-scan {
          0%   { transform: translateX(-300%); opacity: 0.2; }
          20%  { opacity: 0.6; }
          80%  { opacity: 0.6; }
          100% { transform: translateX(300%); opacity: 0.2; }
        }
      `}</style>
    </div>
  );

  return (
    <div
      className="relative w-full h-full bg-[#0d0800] border border-[#2a3a2a] rounded group touch-none select-none"
      ref={containerRef}
      onPointerDown={handlePointerDown}
      onPointerMove={handlePointerMove}
      onPointerUp={handlePointerUp}
      onWheel={handleWheel}
      style={{ cursor: dragMode.current === 'pan' ? 'grabbing' : 'col-resize' }}
    >
      {/* Waveform + scanline (clipped) */}
      <div className="absolute inset-0 overflow-hidden rounded">
        {/* Scanline overlay */}
        <div className="absolute inset-0 pointer-events-none z-10 opacity-30" style={{
          background: 'repeating-linear-gradient(0deg, transparent, transparent 2px, rgba(0,0,0,0.15) 2px, rgba(0,0,0,0.15) 4px)'
        }} />
        <canvas ref={canvasRef} className="w-full h-full opacity-40" />
      </div>

      {/* Loop Region Shading */}
      <div className="absolute top-0 bottom-0 pointer-events-none" style={{
        left: `${loopStart * 100}%`,
        width: `${(loopEnd - loopStart) * 100}%`,
        background: 'rgba(255, 153, 0, 0.1)',
        borderLeft: '1px solid rgba(255, 153, 0, 0.5)',
        borderRight: '1px solid rgba(255, 153, 0, 0.5)',
        boxShadow: 'inset 0 0 10px rgba(255, 153, 0, 0.2)'
      }} />

      {/* Loop Start Handle */}
      <div className="absolute top-0 bottom-0 w-5 -translate-x-1/2 flex items-center justify-center cursor-ew-resize z-20" style={{ left: `${loopStart * 100}%` }}>
        {/* Metallic handle bar */}
        <div className="w-[6px] h-full rounded-sm" style={{
          background: 'linear-gradient(to right, #8a7e70, #c5bdb0, #a89e90, #7a7468)',
          boxShadow: 'inset 0 1px 0 rgba(255,255,255,0.3), inset 0 -1px 0 rgba(0,0,0,0.3), 0 0 6px rgba(255,153,0,0.4), 2px 0 4px rgba(0,0,0,0.5)',
          borderLeft: '1px solid #5a5248',
          borderRight: '1px solid #5a5248',
        }}>
          {/* Grip ridges */}
          <div className="w-full h-full flex flex-col items-center justify-center gap-[3px] opacity-60">
            <div className="w-[3px] h-[1px] bg-[#5a5248] rounded-full shadow-[0_1px_0_rgba(255,255,255,0.2)]" />
            <div className="w-[3px] h-[1px] bg-[#5a5248] rounded-full shadow-[0_1px_0_rgba(255,255,255,0.2)]" />
            <div className="w-[3px] h-[1px] bg-[#5a5248] rounded-full shadow-[0_1px_0_rgba(255,255,255,0.2)]" />
            <div className="w-[3px] h-[1px] bg-[#5a5248] rounded-full shadow-[0_1px_0_rgba(255,255,255,0.2)]" />
            <div className="w-[3px] h-[1px] bg-[#5a5248] rounded-full shadow-[0_1px_0_rgba(255,255,255,0.2)]" />
          </div>
        </div>
        {/* IN label tab */}
        <div className="absolute -top-0 bg-gradient-to-b from-[#c5bdb0] to-[#a89e90] text-[#3a3530] text-[6px] font-bold px-1.5 py-[1px] rounded-b border border-[#8a857a] border-t-0 shadow-[0_2px_3px_rgba(0,0,0,0.4)]">IN</div>
      </div>

      {/* Loop End Handle */}
      <div className="absolute top-0 bottom-0 w-5 -translate-x-1/2 flex items-center justify-center cursor-ew-resize z-20" style={{ left: `${loopEnd * 100}%` }}>
        {/* Metallic handle bar */}
        <div className="w-[6px] h-full rounded-sm" style={{
          background: 'linear-gradient(to right, #8a7e70, #c5bdb0, #a89e90, #7a7468)',
          boxShadow: 'inset 0 1px 0 rgba(255,255,255,0.3), inset 0 -1px 0 rgba(0,0,0,0.3), 0 0 6px rgba(255,153,0,0.4), -2px 0 4px rgba(0,0,0,0.5)',
          borderLeft: '1px solid #5a5248',
          borderRight: '1px solid #5a5248',
        }}>
          {/* Grip ridges */}
          <div className="w-full h-full flex flex-col items-center justify-center gap-[3px] opacity-60">
            <div className="w-[3px] h-[1px] bg-[#5a5248] rounded-full shadow-[0_1px_0_rgba(255,255,255,0.2)]" />
            <div className="w-[3px] h-[1px] bg-[#5a5248] rounded-full shadow-[0_1px_0_rgba(255,255,255,0.2)]" />
            <div className="w-[3px] h-[1px] bg-[#5a5248] rounded-full shadow-[0_1px_0_rgba(255,255,255,0.2)]" />
            <div className="w-[3px] h-[1px] bg-[#5a5248] rounded-full shadow-[0_1px_0_rgba(255,255,255,0.2)]" />
            <div className="w-[3px] h-[1px] bg-[#5a5248] rounded-full shadow-[0_1px_0_rgba(255,255,255,0.2)]" />
          </div>
        </div>
        {/* OUT label tab */}
        <div className="absolute -top-0 bg-gradient-to-b from-[#c5bdb0] to-[#a89e90] text-[#3a3530] text-[6px] font-bold px-1 py-[1px] rounded-b border border-[#8a857a] border-t-0 shadow-[0_2px_3px_rgba(0,0,0,0.4)]">OUT</div>
      </div>

      {/* Playhead */}
      <div className="absolute top-0 bottom-0 w-0.5 will-change-transform z-20 pointer-events-none" style={{
        left: `${progress * 100}%`,
        background: '#ff9900',
        boxShadow: '0 0 10px rgba(255, 153, 0, 0.8), 0 0 4px rgba(255, 255, 255, 0.9)',
      }} />
    </div>
  );
};

