export default function App() {
  // Inject custom CSS at mount
  useEffect(() => {
    const styleEl = document.createElement('style');
    styleEl.textContent = INJECTED_CSS;
    document.head.appendChild(styleEl);
    return () => { styleEl.remove(); };
  }, []);

  const [knobSize, setKnobSize] = useState(() => {
    const h = typeof window !== 'undefined' ? window.innerHeight : 900;
    if (h < 750) return 30; // Aggressive scale for short screens
    return h < 850 ? 36 : h < 1100 ? 44 : 56;
  });

  useEffect(() => {
    const onResize = () => {
      const h = window.innerHeight;
      if (h < 750) setKnobSize(30);
      else setKnobSize(h < 850 ? 36 : h < 1100 ? 44 : 56);
    };
    window.addEventListener('resize', onResize);
    return () => window.removeEventListener('resize', onResize);
  }, []);

  const [appState, setAppState] = useState<'IDLE' | 'EXTRACTING' | 'READY' | 'ERROR' | 'SAVING'>('IDLE');
  const [isPlaying, setIsPlaying] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [isRecording, setIsRecording] = useState(false);
  const [isExporting, setIsExporting] = useState(false);
  const [extractProgress, setExtractProgress] = useState(0);
  const [fileName, setFileName] = useState("NO MEDIA");
  const [errorMsg, setErrorMsg] = useState("");

  // Granular Params
  const [playSpeed, setPlaySpeed] = useState(1);
  const [grainSpeed, setGrainSpeed] = useState(1);
  const [grainSize, setGrainSize] = useState(0.1);
  const [jitter, setJitter] = useState(0);
  const [grainReverse, setGrainReverse] = useState(false);
  const [boomerang, setBoomerang] = useState(false);
  const preBoomerangSpeedRef = useRef<number | null>(null);

  // FX Params
  const [reverbWet, setReverbWet] = useState(0);
  const [roomSize, setRoomSize] = useState(0.5);
  const [delayWet, setDelayWet] = useState(0);
  const [delayFeedback, setDelayFeedback] = useState(0.3);
  const [masterGain, setMasterGain] = useState(0); // dB, range -24 to +6
  const [delayTime, setDelayTime] = useState(0.25);

  // Visual FX Params
  const [echo, setEcho] = useState(0);
  const [smear, setSmear] = useState(0);
  const [crtFx, setCrtFx] = useState(false);
  const [glitchFx, setGlitchFx] = useState(false);

  // Refs
  const playerRef = useRef<Tone.GrainPlayer | null>(null);
  const reverbRef = useRef<Tone.Freeverb | null>(null);
  const delayRef  = useRef<Tone.FeedbackDelay | null>(null);
  const limiterRef = useRef<Tone.Limiter | null>(null);
  const meterRef = useRef<Tone.Meter | null>(null);
  const [vuLevel, setVuLevel] = useState(-Infinity);
  const [actualDirection, setActualDirection] = useState(1);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const glCanvasRef = useRef<HTMLCanvasElement>(null);
  const crtShaderRef = useRef<CRTShader | null>(null);
  const crtFxRef = useRef(false);
  const glitchFxRef = useRef(false);
  const audioBufferRef = useRef<Tone.ToneAudioBuffer | null>(null);
  const framesRef = useRef<ImageBitmap[]>([]);
  const durationRef = useRef(1);
  const fps = 24;

  const loopRegion = useRef({ start: 0, end: 1 });
  const [uiLoop, setUiLoop] = useState({ start: 0, end: 1 });
  const [renderProgress, setRenderProgress] = useState(0);
  const rafRef = useRef<number>(0);
  const lastRafTimeRef = useRef<number | null>(null);
  const playbackStartTimeRef = useRef(0);
  const lastSpacePressRef = useRef<number>(0);
  const lastJitterUpdateRef = useRef<number>(0);
  const currentJitterOffsetRef = useRef<number>(0);

  const playheadRef = useRef(0);
  const isPlayingRef = useRef(false);
  const playSpeedRef = useRef(1);
  const grainSpeedRef = useRef(1);
  const grainSizeRef = useRef(0.1);
  const jitterRef = useRef(0);
  const grainReverseRef = useRef(false);
  const smearRef = useRef(0);
  const echoRef = useRef(0);
  const boomerangRef = useRef(false);
  const directionRef = useRef(1);

  const smearFeedbackRef = useRef<HTMLCanvasElement | null>(null);
  const performanceRecorderRef = useRef<MediaRecorder | null>(null);
  const [videoDims, setVideoDims] = useState({ width: 640, height: 360 });

  const cleanup = useCallback(() => {
    cancelAnimationFrame(rafRef.current);
    if (playerRef.current) { 
      try { playerRef.current.stop(); } catch(e) {}
      playerRef.current.dispose(); 
      playerRef.current = null; 
    }
    reverbRef.current?.dispose(); reverbRef.current = null;
    delayRef.current?.dispose();  delayRef.current  = null;
    limiterRef.current?.dispose(); limiterRef.current = null;
    meterRef.current?.dispose(); meterRef.current = null;
    framesRef.current.forEach(bmp => bmp.close());
    framesRef.current = [];
    audioBufferRef.current = null;
    isPlayingRef.current = false;
    playbackStartTimeRef.current = 0;
    lastRafTimeRef.current = null;
    playheadRef.current = 0;
    if (smearFeedbackRef.current) {
      const fbCtx = smearFeedbackRef.current.getContext('2d');
      if (fbCtx) fbCtx.clearRect(0, 0, smearFeedbackRef.current.width, smearFeedbackRef.current.height);
    }
    setIsPlaying(false);
    setIsExporting(false);
  }, []);

  const handleFlowMediaSelect = async () => {
    try {
      const media = await Flow.media.select({ filter: 'video' });
      if (!media) return;
      const bytes = Uint8Array.from(atob(media.base64), c => c.charCodeAt(0));
      const blob = new Blob([bytes], { type: media.mimeType });
      const file = new File([blob], media.name || 'video.mp4', { type: media.mimeType });
      processMedia(file);
    } catch (err) {
      console.error('Flow media select error:', err);
    }
  };

  const processMedia = async (file: File) => {
    cleanup();
    setAppState('EXTRACTING');
    setFileName(file.name);
    setExtractProgress(0);

    try {
      await Tone.start();
      const arrayBuffer = await file.arrayBuffer();
      let audioBuf: Tone.ToneAudioBuffer;
      try {
        const audioClone = arrayBuffer.slice(0);
        const decoded = await Tone.context.decodeAudioData(audioClone);
        audioBuf = new Tone.ToneAudioBuffer(decoded);
      } catch (e) {
        const silentBuf = Tone.context.createBuffer(1, Tone.context.sampleRate * 2, Tone.context.sampleRate);
        audioBuf = new Tone.ToneAudioBuffer(silentBuf);
      }

      const fileDuration = Math.max(0.5, Math.min(audioBuf.duration || 5, 15));
      durationRef.current = fileDuration;
      audioBufferRef.current = audioBuf;

      const videoUrl = URL.createObjectURL(file);
      const video = document.createElement('video');
      video.muted = true;
      video.playsInline = true;
      video.preload = 'auto';
      video.src = videoUrl;

      await new Promise<void>((resolve, reject) => {
        video.onloadedmetadata = () => resolve();
        video.onerror = () => reject(new Error("Failed to load video"));
      });

      if (video.readyState < 2) {
        await new Promise<void>((resolve) => {
          video.oncanplay = () => resolve();
          setTimeout(resolve, 3000);
        });
      }

      let targetW = video.videoWidth || 1080;
      let targetH = video.videoHeight || 1080;
      const maxDim = 1080;
      if (Math.max(targetW, targetH) > maxDim) {
        const scale = maxDim / Math.max(targetW, targetH);
        targetW = Math.round(targetW * scale);
        targetH = Math.round(targetH * scale);
      }
      setVideoDims({ width: targetW, height: targetH });

      const offscreen = document.createElement('canvas');
      offscreen.width = targetW;
      offscreen.height = targetH;
      const ctx = offscreen.getContext('2d', { willReadFrequently: true });
      if (!ctx) throw new Error("Canvas context failed");

      const workingDuration = Math.min(fileDuration, Math.min(video.duration || fileDuration, 15));
      durationRef.current = workingDuration;
      const totalFrames = Math.floor(workingDuration * fps);
      const extractedFrames: ImageBitmap[] = [];

      const seekAndWait = (v: HTMLVideoElement, time: number): Promise<void> => {
        return new Promise<void>((resolve) => {
          const onSeeked = () => {
            v.removeEventListener('seeked', onSeeked);
            setTimeout(resolve, 16);
          };
          v.addEventListener('seeked', onSeeked);
          if (Math.abs(v.currentTime - time) < 0.001) {
            v.currentTime = time + 0.001;
            v.addEventListener('seeked', function nudged() {
              v.removeEventListener('seeked', nudged);
              v.addEventListener('seeked', onSeeked);
              v.currentTime = time;
            }, { once: true });
          } else {
            v.currentTime = time;
          }
          setTimeout(() => { v.removeEventListener('seeked', onSeeked); resolve(); }, 500);
        });
      };

      for (let i = 0; i < totalFrames; i++) {
        await seekAndWait(video, i / fps);
        ctx.fillStyle = '#000';
        ctx.fillRect(0, 0, targetW, targetH);
        ctx.drawImage(video, 0, 0, targetW, targetH);
        extractedFrames.push(await createImageBitmap(offscreen));
        setExtractProgress(((i + 1) / totalFrames) * 100);
      }

      framesRef.current = extractedFrames;
      URL.revokeObjectURL(videoUrl);

      const player = new Tone.GrainPlayer({
        url: audioBuf,
        loop: true,
        grainSize: Math.max(0.02, grainSize),
        overlap: Math.max(0.02, grainSize) * 0.5,
        playbackRate: grainSpeed,
        reverse: grainReverse,
        loopStart: 0,
        loopEnd: workingDuration,
      });

      const reverb = new Tone.Freeverb({ roomSize, wet: reverbWet });
      const delay  = new Tone.FeedbackDelay({ delayTime, feedback: delayFeedback, wet: delayWet * 0.5 });
      const limiter = new Tone.Limiter(-6);
      player.connect(delay);
      delay.connect(reverb);
      reverb.connect(limiter);
      limiter.toDestination();

      const meter = new Tone.Meter({ smoothing: 0.8 });
      limiter.connect(meter);

      playerRef.current = player;
      reverbRef.current = reverb;
      delayRef.current  = delay;
      limiterRef.current = limiter;
      meterRef.current = meter;

      loopRegion.current = { start: 0, end: 1 };
      setUiLoop({ start: 0, end: 1 });
      playheadRef.current = 0;
      setAppState('READY');
      drawInitialFrame();
      // Ensure shader is instantiated if not already
      if (glCanvasRef.current && !crtShaderRef.current) {
        crtShaderRef.current = new CRTShader(glCanvasRef.current);
      }
      setTimeout(() => handlePlay(), 150);
    } catch (err) {
      setErrorMsg("MEDIA PROCESSING ERROR.");
      setAppState('ERROR');
    }
  };

  const drawInitialFrame = () => {
    if (!framesRef.current.length || !canvasRef.current) return;
    const canvas = canvasRef.current;
    const frame = framesRef.current[0];
    canvas.width = frame.width;
    canvas.height = frame.height;
    const ctx = canvas.getContext('2d');
    if (ctx) ctx.drawImage(frame, 0, 0, canvas.width, canvas.height);
  };

  useEffect(() => { playSpeedRef.current = playSpeed; }, [playSpeed]);
  useEffect(() => { grainSpeedRef.current = grainSpeed; if (playerRef.current) playerRef.current.playbackRate = grainSpeed; }, [grainSpeed]);
  useEffect(() => { 
    grainSizeRef.current = grainSize; 
    if (playerRef.current) {
      const actualSize = Math.max(0.02, grainSize);
      playerRef.current.grainSize = actualSize;
      playerRef.current.overlap = actualSize * 0.5;
    } 
  }, [grainSize]);
  useEffect(() => { jitterRef.current = jitter; }, [jitter]);
  useEffect(() => { grainReverseRef.current = grainReverse; }, [grainReverse]);
  useEffect(() => { boomerangRef.current = boomerang; if (!boomerang) directionRef.current = 1; }, [boomerang]);
  useEffect(() => { Tone.getDestination().volume.value = masterGain; }, [masterGain]);
  useEffect(() => { smearRef.current = smear; }, [smear]);
  useEffect(() => { echoRef.current = echo; }, [echo]);
  useEffect(() => { 
    crtFxRef.current = crtFx; 
    // Proactive Init on toggle
    if (crtFx && glCanvasRef.current && !crtShaderRef.current) {
      try { crtShaderRef.current = new CRTShader(glCanvasRef.current); } catch(e){}
    }
  }, [crtFx]);
  useEffect(() => { 
    glitchFxRef.current = glitchFx; 
    // Proactive Init on toggle
    if (glitchFx && glCanvasRef.current && !crtShaderRef.current) {
      try { crtShaderRef.current = new CRTShader(glCanvasRef.current); } catch(e){}
    }
  }, [glitchFx]);

  useEffect(() => { if (reverbRef.current) reverbRef.current.wet.value = reverbWet; }, [reverbWet]);
  useEffect(() => { if (reverbRef.current) reverbRef.current.roomSize.value = roomSize; }, [roomSize]);
  useEffect(() => { 
    if (delayRef.current) { 
      // Surgical adjustment: map 0-1 knob to 0-0.5 internal wetness.
      // This ensures that at "max delay" we hear a 50/50 mix of Dry/Wet, 
      // making a single tap noticeably distinct from the dry source grains.
      delayRef.current.wet.value = delayWet * 0.5; 
    } 
  }, [delayWet]);
  useEffect(() => { if (delayRef.current) delayRef.current.feedback.value = delayFeedback; }, [delayFeedback]);
  useEffect(() => { if (delayRef.current) delayRef.current.delayTime.value = delayTime; }, [delayTime]);

  const handlePlay = async () => {
    if (!playerRef.current || isPlayingRef.current) return;
    if (Tone.context.state !== 'running') await Tone.start();

    // SURGICAL: Ensure all granular params are explicitly synced from refs 
    // to the GrainPlayer instance immediately before start. This ensures 
    // that settings adjusted while paused (like Size) are applied instantly.
    if (playerRef.current) {
      const p = playerRef.current;
      const gs = Math.max(0.02, grainSizeRef.current);
      p.grainSize = gs;
      p.overlap = gs * 0.5;
      p.playbackRate = grainSpeedRef.current;
      p.reverse = grainReverseRef.current;
    }

    const startTime = Tone.now() + 0.05; 
    playerRef.current.start(startTime);
    setIsPaused(false);
    isPlayingRef.current = true;
    playbackStartTimeRef.current = startTime;
    lastRafTimeRef.current = null;
    setIsPlaying(true);
    startSyncLoop();
  };

  const handleStop = () => {
    if (performanceRecorderRef.current?.state === 'recording') performanceRecorderRef.current.stop();
    playerRef.current?.stop();
    isPlayingRef.current = false;
    setIsPlaying(false);
    setIsExporting(false);
    cancelAnimationFrame(rafRef.current);
    setVuLevel(-Infinity);
    const lStart = loopRegion.current.start * durationRef.current;
    playheadRef.current = lStart;
    setRenderProgress(loopRegion.current.start);
    if (framesRef.current.length && canvasRef.current) blendedDraw(canvasRef.current, lStart);
    setIsPaused(false);
  };

  const handlePause = () => {
    if (performanceRecorderRef.current?.state === 'recording') performanceRecorderRef.current.stop();
    playerRef.current?.stop();
    isPlayingRef.current = false;
    setIsPlaying(false);
    setIsExporting(false);
    cancelAnimationFrame(rafRef.current);
    setVuLevel(-Infinity);
    setIsPaused(true);
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.code === 'Space') {
        if (document.activeElement?.tagName === 'INPUT' || document.activeElement?.tagName === 'TEXTAREA') return;
        e.preventDefault();
        if (isPlayingRef.current) handlePause(); else handlePlay();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, []);

  const handleRecord = () => {
    if (appState !== 'READY' || !playerRef.current || !canvasRef.current) return;
    if (isExporting) { handleStop(); return; }
    setupPerformanceRecorder();
    if (!isPlaying) handlePlay();
    setIsExporting(true);
  };

  const setupPerformanceRecorder = () => {
    if (!canvasRef.current) return;
    const stream = canvasRef.current.captureStream(30);
    const audioCtx = Tone.getContext().rawContext;
    const dest = (audioCtx as AudioContext).createMediaStreamDestination();
    Tone.getDestination().connect(dest);
    const combined = new MediaStream([...stream.getVideoTracks(), ...dest.stream.getAudioTracks()]);
    const recorder = new MediaRecorder(combined, { mimeType: 'video/webm;codecs=vp9,opus' });
    const chunks: BlobPart[] = [];
    recorder.ondataavailable = e => { if (e.data.size > 0) chunks.push(e.data); };
    recorder.onstop = async () => {
      const blob = new Blob(chunks, { type: 'video/webm' });
      const buffer = await blob.arrayBuffer();
      const bytes = new Uint8Array(buffer);
      let binary = '';
      for (let i = 0; i < bytes.length; i++) binary += String.fromCharCode(bytes[i]);
      await Flow.save({ base64: btoa(binary), mimeType: 'video/webm', name: 'TimeWarp-Performance.webm' });
    };
    performanceRecorderRef.current = recorder;
    recorder.start();
  };

  const handleLoopChange = (start: number, end: number) => {
    const s = Math.max(0, Math.min(start, end - 0.05));
    const e = Math.min(1, Math.max(s + 0.05, end));
    loopRegion.current = { start: s, end: e };
    setUiLoop({ start: s, end: e });
    playheadRef.current = Math.max(s * durationRef.current, Math.min(e * durationRef.current, playheadRef.current));
    const loopDur = Math.max(0.01, (e - s) * durationRef.current);
    setRenderProgress(s + ((playheadRef.current - s * durationRef.current) / loopDur) * (e - s));
    if (!isPlayingRef.current && framesRef.current.length && canvasRef.current) blendedDraw(canvasRef.current, playheadRef.current);
  };

  const handleLoopPan = useCallback((deltaNorm: number) => {
    const { start, end } = loopRegion.current;
    if (start + deltaNorm >= 0 && end + deltaNorm <= 1) handleLoopChange(start + deltaNorm, end + deltaNorm);
  }, []);

  const handleLoopZoom = useCallback((factor: number, centerNorm: number) => {
    const { start, end } = loopRegion.current;
    const half = (end - start) / 2;
    const newHalf = Math.max(0.025, Math.min(0.5, half * factor));
    handleLoopChange(Math.max(0, centerNorm - newHalf), Math.min(1, centerNorm + newHalf));
  }, []);

  const blendedDraw = useCallback((canvas: HTMLCanvasElement | null, ph: number) => {
    if (!canvas || !framesRef.current.length) return;
    const frames = framesRef.current;
    const ctx = canvas.getContext('2d')!;
    const exactIndex = (ph / durationRef.current) * frames.length;
    const indexA = Math.max(0, Math.min(frames.length - 1, Math.floor(exactIndex)));

    if (canvas.width !== frames[indexA].width) { canvas.width = frames[indexA].width; canvas.height = frames[indexA].height; }
    const w = canvas.width, h = canvas.height;

    ctx.globalAlpha = 1.0;
    ctx.drawImage(frames[indexA], 0, 0, w, h);

    const gs = grainSizeRef.current;
    const grainFrameSpan = Math.floor(gs * 24);
    if ((smearRef.current > 0.01 || echoRef.current > 0.01) && grainFrameSpan > 1) {
      const halfSpan = Math.floor(grainFrameSpan / 2);
      for (let offset = -halfSpan; offset <= halfSpan; offset++) {
        const neighborIdx = Math.max(0, Math.min(frames.length - 1, indexA + offset));
        if (neighborIdx === indexA) continue;
        const alpha = 0.4 * (1.0 - Math.abs(offset) / (halfSpan + 1));
        if (alpha > 0.01) { ctx.globalAlpha = alpha; ctx.drawImage(frames[neighborIdx], 0, 0, w, h); }
      }
    }

    if (echoRef.current > 0.01) {
      const taps = Math.round(echoRef.current * 8);
      for (let t = 1; t <= taps; t++) {
        const offset = t * Math.max(3, Math.round(echoRef.current * frames.length * 0.06));
        const tapAlpha = (0.2 + echoRef.current * 0.3) * (1.0 - (t - 1) / taps);
        const idxF = Math.min(frames.length - 1, indexA + offset);
        const idxB = Math.max(0, indexA - offset);
        if (idxF !== indexA) { ctx.globalAlpha = tapAlpha; ctx.drawImage(frames[idxF], 0, 0, w, h); }
        if (idxB !== indexA) { ctx.globalAlpha = tapAlpha * 0.7; ctx.drawImage(frames[idxB], 0, 0, w, h); }
      }
    }

    if (smearRef.current > 0.01) {
      if (!smearFeedbackRef.current) smearFeedbackRef.current = document.createElement('canvas');
      const fb = smearFeedbackRef.current;
      if (fb.width !== w) { fb.width = w; fb.height = h; }
      const fbCtx = fb.getContext('2d')!;
      ctx.globalAlpha = smearRef.current;
      ctx.drawImage(fb, 0, 0);
      fbCtx.globalAlpha = 1.0; fbCtx.clearRect(0, 0, w, h); fbCtx.drawImage(canvas, 0, 0);
    }
    ctx.globalAlpha = 1.0;
  }, []);

  const handleTimelineSeek = useCallback((normPos: number) => {
    const lS = loopRegion.current.start * durationRef.current;
    const lE = loopRegion.current.end * durationRef.current;
    const dur = Math.max(0.01, lE - lS);
    let p = normPos * durationRef.current;

    // SURGICAL: CENTRALIZED WRAP/BOUNCE LOGIC
    if (boomerangRef.current) {
        const rel = p - lS;
        const dDur = dur * 2;
        const w = ((rel % dDur) + dDur) % dDur;
        p = lS + (w > dur ? dDur - w : w);
    } else {
        const rel = p - lS;
        const w = ((rel % dur) + dur) % dur;
        p = lS + w;
    }

    playheadRef.current = p;
    const normInLoop = (p - lS) / dur;
    setRenderProgress(loopRegion.current.start + normInLoop * (loopRegion.current.end - loopRegion.current.start));
    if (!isPlayingRef.current && framesRef.current.length && canvasRef.current) blendedDraw(canvasRef.current, playheadRef.current);
  }, [blendedDraw]);

  const startSyncLoop = () => {
    let lastProgressDraw = 0;
    let lastDirectionLocal = directionRef.current;
    const update = (rafTime: number) => {
      if (!isPlayingRef.current || !framesRef.current.length || !canvasRef.current) { if (isPlayingRef.current) rafRef.current = requestAnimationFrame(update); return; }
      if (lastRafTimeRef.current === null) lastRafTimeRef.current = rafTime;
      const dtSec = Math.min(rafTime - lastRafTimeRef.current, 100) / 1000;
      lastRafTimeRef.current = rafTime;

      const elapsed = Tone.now() - playbackStartTimeRef.current;
      if (elapsed < 0) { rafRef.current = requestAnimationFrame(update); return; }

      const lStart = loopRegion.current.start * durationRef.current;
      const lEnd   = loopRegion.current.end   * durationRef.current;
      const loopDur = Math.max(0.01, lEnd - lStart);
      const s = playSpeedRef.current;

      if (boomerangRef.current) {
        playheadRef.current += dtSec * Math.abs(s) * directionRef.current;
        if (playheadRef.current >= lEnd) { playheadRef.current = lEnd - (playheadRef.current - lEnd); directionRef.current = -1; }
        else if (playheadRef.current <= lStart) { playheadRef.current = lStart + (lStart - playheadRef.current); directionRef.current = 1; }

        // Sync actual direction state for UI visibility
        if (directionRef.current !== lastDirectionLocal) {
          lastDirectionLocal = directionRef.current;
          setActualDirection(directionRef.current);
        }
      } else {
        playheadRef.current += dtSec * s;
        while (playheadRef.current >= lEnd) playheadRef.current -= loopDur;
        while (playheadRef.current < lStart) playheadRef.current += loopDur;
      }

      // SURGICAL FIX: The REV toggle now strictly controls grain direction.
      // Decoupled from traversal direction (playSpeed) to ensure the timeline matches visuals.
      const finalReverse = grainReverseRef.current;

      const gs = Math.max(0.02, grainSizeRef.current);
      if (rafTime - lastJitterUpdateRef.current > gs * 1000) {
        currentJitterOffsetRef.current = (Math.random() - 0.5) * jitterRef.current * 1.5;
        lastJitterUpdateRef.current = rafTime;
      }
      const jitteredPh = Math.max(lStart, Math.min(lEnd, playheadRef.current + currentJitterOffsetRef.current));

      // Standardize the grain window to [jitteredPh, jitteredPh + gs] (with safety clamping).
      let gStart = jitteredPh;
      let gEnd = jitteredPh + gs;
      if (gEnd > lEnd) {
        gEnd = lEnd;
        gStart = Math.max(lStart, lEnd - gs);
      }
      const actualGs = gEnd - gStart;

      if (playerRef.current) {
        const player = playerRef.current;
        player.reverse = finalReverse;
        // TONE.JS REVERSE FIX: 
        // GrainPlayer.reverse flips the buffer indices. We must mirror our loop bounds 
        // (dur - pos) to ensure the playhead continues to point at the correct audio content.
        if (finalReverse && audioBufferRef.current) {
          const dur = audioBufferRef.current.duration;
          player.loopStart = Math.max(0, dur - gEnd);
          player.loopEnd = Math.min(dur, dur - gStart);
        } else {
          player.loopStart = gStart;
          player.loopEnd = gEnd;
        }
      }

      const gSpeed = Math.abs(grainSpeedRef.current);
      const grainPeriod = Math.max(0.005, (actualGs - 0.002) / gSpeed);
      const grainTime = Math.max(0, elapsed) % grainPeriod;
      const internalOffset = Math.min(actualGs, grainTime * gSpeed);

      // Visual modulatedPh synchronization:
      // If forward: gStart -> gStart + offset
      // If reverse: gEnd -> gEnd - offset
      const modulatedPh = gStart + (finalReverse ? (actualGs - internalOffset) : internalOffset);

      blendedDraw(canvasRef.current, Math.max(0, Math.min(durationRef.current, modulatedPh)));

      // Robust Shader Logic
      if ((crtFxRef.current || glitchFxRef.current) && canvasRef.current) {
        // Lazy Init if needed
        if (!crtShaderRef.current && glCanvasRef.current) {
          try { crtShaderRef.current = new CRTShader(glCanvasRef.current); } catch(e){}
        }
        if (crtShaderRef.current) {
          crtShaderRef.current.render(canvasRef.current, { crt: crtFxRef.current, glitch: glitchFxRef.current, time: rafTime / 1000 });
        }
      }

      if (rafTime - lastProgressDraw > 33) {
        const normProgress = (jitteredPh - lStart) / loopDur;
        setRenderProgress(loopRegion.current.start + normProgress * (loopRegion.current.end - loopRegion.current.start));
        if (meterRef.current) { const lev = meterRef.current.getValue(); setVuLevel(typeof lev === 'number' ? lev : lev[0]); }
        lastProgressDraw = rafTime;
      }
      rafRef.current = requestAnimationFrame(update);
    };
    rafRef.current = requestAnimationFrame(update);
  };

  const handleRandomize = () => {
    setPlaySpeed(+(Math.random() * 3 - 1).toFixed(2));
    // SURGICAL: Randomization now allows grain speed to go below 1.0 (range: 0.1 to 4.0)
    setGrainSpeed(+(0.1 + Math.random() * 3.9).toFixed(2));
    setGrainSize(+(0.01 + Math.random() * 0.49).toFixed(3));
    setJitter(+(Math.random()).toFixed(2));
    setGrainReverse(Math.random() > 0.5);
    setReverbWet(+(Math.random()).toFixed(2));
    setRoomSize(+(Math.random()).toFixed(2));
    setDelayWet(+(Math.random()).toFixed(2));
    setDelayFeedback(+(Math.random() * 0.95).toFixed(2));
    setEcho(+(Math.random()).toFixed(2));
    setSmear(+(Math.random()).toFixed(2));
    setBoomerang(Math.random() > 0.5);
  };

  const handleReset = () => {
    setPlaySpeed(1); setGrainSpeed(1); setGrainSize(0.1); setJitter(0); setGrainReverse(false);
    setReverbWet(0); setRoomSize(0.5); setDelayWet(0); setDelayFeedback(0.3); setMasterGain(0); setDelayTime(0.25);
    setEcho(0); setSmear(0); setCrtFx(false); setGlitchFx(false); setBoomerang(false);
  };

  const handleBoomerangToggle = () => {
    setBoomerang(prev => {
      if (!prev) {
        if (playSpeed < 0) { preBoomerangSpeedRef.current = playSpeed; setPlaySpeed(Math.abs(playSpeed)); }
        else preBoomerangSpeedRef.current = null;
