        if (Math.abs(e.deltaY) > 1) {
            // SURGICAL: WRAP/BOUNCE LOGIC FOR GLOBAL WHEEL
            const lS = loopRegion.current.start * durationRef.current;
            const lE = loopRegion.current.end * durationRef.current;
