            let p = playheadRef.current + delta;

            if (boomerangRef.current) {
                const rel = p - lS;
                const dDur = dur * 2;
                const w = ((rel % dDur) + dDur) % dDur;
                p = lS + (w > dur ? dDur - w : w);
            } else {
                const rel = p - lS;
                const w = ((rel % dur) + dur) % dur;
                p = lS + w;
            }

            playheadRef.current = p;
            const normInLoop = (p - lS) / dur;
            setRenderProgress(loopRegion.current.start + normInLoop * (loopRegion.current.end - loopRegion.current.start));
            if (!isPlayingRef.current && framesRef.current.length && canvasRef.current) blendedDraw(canvasRef.current, playheadRef.current);
        }
    }}>
