.led-on {
  background: radial-gradient(circle at 40% 35%, #ffaa33, #cc6600);
  box-shadow: inset 0 1px 2px rgba(0,0,0,0.2), 0 0 5px rgba(255,153,0,0.5);
}

/* ==========================================
   GLOBAL NOISE TEXTURE OVERLAY
   ========================================== */
.noise-overlay {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0.06;
  mix-blend-mode: overlay;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='1.2' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='1'/%3E%3C/svg%3E");
}

/* ==========================================
   SCROLLBAR STYLING (for sidebar)
   ========================================== */
::-webkit-scrollbar {
  width: 6px;
}
::-webkit-scrollbar-track {
  background: #9e978e;
}
::-webkit-scrollbar-thumb {
  background: #807a72;
  border-radius: 3px;
}
::-webkit-scrollbar-thumb:hover {
  background: #6b665e;
}

/* ==========================================
   INPUT RANGE (fallback, mostly unused with knobs)
   ========================================== */
input[type="range"] {
  -webkit-appearance: none;
  width: 100%;
  background: transparent;
}
input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  height: 20px;
  width: 10px;
  background: #4a4540;
  cursor: pointer;
  margin-top: -7px;
  border-radius: 2px;
}
input[type="range"]::-webkit-slider-runnable-track {
  width: 100%;
  height: 6px;
  cursor: pointer;
  background: #1a1816;
  border: 1px solid #555;
  border-radius: 3px;
}

/* === HARDWARE SCROLLBAR === */
.hardware-scrollbar::-webkit-scrollbar {
  width: 10px;
}
.hardware-scrollbar::-webkit-scrollbar-track {
  background: #3a3530;
  border-left: 1px solid #2a2520;
  box-shadow: inset 1px 0 3px rgba(0,0,0,0.4);
}
.hardware-scrollbar::-webkit-scrollbar-thumb {
  background: linear-gradient(180deg, #8a857a, #6b665e);
  border: 1px solid #5a5550;
  border-radius: 2px;
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.15), inset 0 -1px 0 rgba(0,0,0,0.15);
  min-height: 40px;
}
.hardware-scrollbar::-webkit-scrollbar-thumb:hover {
  background: linear-gradient(180deg, #9a958a, #7a756e);
}
.hardware-scrollbar::-webkit-scrollbar-thumb:active {
  background: linear-gradient(180deg, #7a756e, #5a5550);
}
